package com.edward.galleryflow;
import android.content.*;import android.database.*;import android.net.Uri;import android.os.ParcelFileDescriptor;import android.provider.OpenableColumns;import java.io.*;import java.util.*;
/** Explicit read grants expose only completed share copies, never original paths. */
public final class ShareProvider extends ContentProvider {
 public boolean onCreate(){return true;}
 static Uri stage(Context c,Uri source,String name,String mime)throws IOException{File root=new File(c.getCacheDir(),"outgoing-shares");root.mkdirs();File[] old=root.listFiles();if(old!=null)for(File d:old)if(d.isDirectory()&&System.currentTimeMillis()-d.lastModified()>86400000L){File[] files=d.listFiles();if(files!=null)for(File f:files)f.delete();d.delete();}String id=UUID.randomUUID().toString();File dir=new File(root,id);if(!dir.mkdir())throw new IOException("Share storage unavailable");String safe=name.replaceAll("[\\\\/\\p{Cntrl}]","_");if(safe.isEmpty()||safe.startsWith("."))safe="shared-video";File target=new File(dir,safe);try{try(InputStream in=c.getContentResolver().openInputStream(source);OutputStream out=new FileOutputStream(target)){if(in==null)throw new IOException("Unavailable video");byte[] buffer=new byte[65536];int count;while((count=in.read(buffer))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();out.write(buffer,0,count);}}try(DataOutputStream meta=new DataOutputStream(new FileOutputStream(new File(dir,".metadata")))){meta.writeUTF(safe);meta.writeUTF(mime==null?"application/octet-stream":mime);}return new Uri.Builder().scheme("content").authority("com.edward.galleryflow.share").appendPath(id).appendPath(safe).build();}catch(IOException|RuntimeException e){target.delete();new File(dir,".metadata").delete();dir.delete();throw e;}}
 private File file(Uri u)throws FileNotFoundException{try{List<String> paths=u.getPathSegments();if(paths.size()!=2||!paths.get(0).matches("[a-f0-9-]{36}"))throw new IOException();File dir=new File(new File(getContext().getCacheDir(),"outgoing-shares"),paths.get(0));File f=new File(dir,paths.get(1));if(!f.getCanonicalFile().getParentFile().equals(dir.getCanonicalFile()))throw new IOException();try(DataInputStream meta=new DataInputStream(new FileInputStream(new File(dir,".metadata")))){if(!meta.readUTF().equals(paths.get(1)))throw new IOException();}if(!f.isFile())throw new IOException();return f;}catch(IOException e){throw new FileNotFoundException("Share expired or invalid");}}
 public ParcelFileDescriptor openFile(Uri u,String mode)throws FileNotFoundException{if(!"r".equals(mode))throw new FileNotFoundException("Read only");return ParcelFileDescriptor.open(file(u),ParcelFileDescriptor.MODE_READ_ONLY);}
 public String getType(Uri u){try{File f=file(u);try(DataInputStream meta=new DataInputStream(new FileInputStream(new File(f.getParentFile(),".metadata")))){meta.readUTF();return meta.readUTF();}}catch(IOException e){return "application/octet-stream";}}
 public Cursor query(Uri u,String[] projection,String selection,String[] args,String sort){try{File f=file(u);String[] cols=projection==null?new String[]{OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE}:projection;MatrixCursor c=new MatrixCursor(cols);Object[] row=new Object[cols.length];for(int n=0;n<cols.length;n++)row[n]=OpenableColumns.DISPLAY_NAME.equals(cols[n])?f.getName():OpenableColumns.SIZE.equals(cols[n])?f.length():null;c.addRow(row);return c;}catch(IOException e){return null;}}
 public Uri insert(Uri u,ContentValues v){throw new UnsupportedOperationException();}public int update(Uri u,ContentValues v,String s,String[] a){throw new UnsupportedOperationException();}public int delete(Uri u,String s,String[] a){throw new UnsupportedOperationException();}
}
